void cvkParseJsonPhysicalDeviceProperties(const cvkJsonContext* pContext, const cvkJsonValue* pObject, VkPhysicalDeviceProperties* pInfo)
{
    const cvkJsonValue* value;
    uint32_t            index;

    memset(pInfo, 0, sizeof(*pInfo));
    value = cvkGetJsonMember(&pContext->document, pObject, "apiVersion");
    if (!cvkIsJsonNull(value))
    {
        pInfo->apiVersion = (uint32_t)cvkParseJsonUint64(value);
    }
    value = cvkGetJsonMember(&pContext->document, pObject, "driverVersion");
    if (!cvkIsJsonNull(value))
    {
        pInfo->driverVersion = (uint32_t)cvkParseJsonUint64(value);
    }
    value = cvkGetJsonMember(&pContext->document, pObject, "vendorID");
    if (!cvkIsJsonNull(value))
    {
        pInfo->vendorID = (uint32_t)cvkParseJsonUint64(value);
    }
    value = cvkGetJsonMember(&pContext->document, pObject, "deviceID");
    if (!cvkIsJsonNull(value))
    {
        pInfo->deviceID = (uint32_t)cvkParseJsonUint64(value);
    }
    value = cvkGetJsonMember(&pContext->document, pObject, "deviceType");
    if (!cvkIsJsonNull(value))
    {
        pInfo->deviceType = cvkParseJsonPhysicalDeviceType(value);
    }
    value = cvkGetJsonMember(&pContext->document, pObject, "deviceName");
    if (!cvkIsJsonNull(value))
    {
        if (CVK_JSON_STRING == value->kind)
        {
            memcpy(pInfo->deviceName, value->pText, (value->textLength < sizeof(pInfo->deviceName)) ? value->textLength : sizeof(pInfo->deviceName) - 1);
        }
    }
    value = cvkGetJsonMember(&pContext->document, pObject, "pipelineCacheUUID");
    if (!cvkIsJsonNull(value))
    {
        if (CVK_JSON_ARRAY == value->kind)
        {
            for (index = 0; index < value->childCount && index < VK_UUID_SIZE; ++index)
            {
                pInfo->pipelineCacheUUID[index] = (uint8_t)cvkParseJsonUint64(cvkGetJsonElement(&pContext->document, value, index));
            }
        }
    }
    value = cvkGetJsonMember(&pContext->document, pObject, "limits");
    if (!cvkIsJsonNull(value))
    {
        cvkParseJsonPhysicalDeviceLimits(pContext, value, &pInfo->limits);
    }
    value = cvkGetJsonMember(&pContext->document, pObject, "sparseProperties");
    if (!cvkIsJsonNull(value))
    {
        cvkParseJsonPhysicalDeviceSparseProperties(pContext, value, &pInfo->sparseProperties);
    }
}
