void cvkCmdTransferImageToImage2D(VkCommandBuffer          commandBuffer,
                                  VkDependencyFlags        dependencyFlags,
                                  const void*              pSrcAcquireBarrierNext,
                                  VkPipelineStageFlags     srcStageMask,
                                  VkAccessFlags            srcAccessMask,
                                  VkImageLayout            srcInitialLayout,
                                  VkImageLayout            srcTransferLayout,
                                  VkImage                  srcImage,
                                  VkImageSubresourceLayers srcSubresource,
                                  const void*              pDstAcquireBarrierNext,
                                  VkPipelineStageFlags     dstStageMask,
                                  VkAccessFlags            dstAccessMask,
                                  VkImageLayout            dstInitialLayout,
                                  VkImageLayout            dstTransferLayout,
                                  VkImage                  dstImage,
                                  VkImageSubresourceLayers dstSubresource,
                                  const void*              pSrcBarrierNext,
                                  VkPipelineStageFlags     srcDstStageMask,
                                  VkAccessFlags            srcDstAccessMask,
                                  VkImageLayout            srcFinalLayout,
                                  const void*              pDstBarrierNext,
                                  VkPipelineStageFlags     dstDstStageMask,
                                  VkAccessFlags            dstDstAccessMask,
                                  VkImageLayout            dstFinalLayout,
                                  VkOffset2D               srcOffset2D,
                                  VkOffset2D               dstOffset2D,
                                  VkExtent2D               extent2D)
{
    VkOffset3D src_offset;
    VkOffset3D dst_offset;
    VkExtent3D extent;

    cvkInitOffset3D(&src_offset, srcOffset2D.x, srcOffset2D.y, 0);
    cvkInitOffset3D(&dst_offset, dstOffset2D.x, dstOffset2D.y, 0);
    cvkInitExtent3D(&extent, extent2D.width, extent2D.height, 1);
    cvkCmdTransferImageToImage(commandBuffer,
                               dependencyFlags,
                               pSrcAcquireBarrierNext,
                               srcStageMask,
                               srcAccessMask,
                               srcInitialLayout,
                               srcTransferLayout,
                               srcImage,
                               srcSubresource,
                               src_offset,
                               pDstAcquireBarrierNext,
                               dstStageMask,
                               dstAccessMask,
                               dstInitialLayout,
                               dstTransferLayout,
                               dstImage,
                               dstSubresource,
                               dst_offset,
                               extent,
                               pSrcBarrierNext,
                               srcDstStageMask,
                               srcDstAccessMask,
                               srcFinalLayout,
                               pDstBarrierNext,
                               dstDstStageMask,
                               dstDstAccessMask,
                               dstFinalLayout);
}
void cvkCmdTransferBlitImage2D(VkCommandBuffer          commandBuffer,
                               VkDependencyFlags        dependencyFlags,
                               const void*              pSrcAcquireBarrierNext,
                               VkPipelineStageFlags     srcStageMask,
                               VkAccessFlags            srcAccessMask,
                               VkImageLayout            srcInitialLayout,
                               VkImageLayout            srcTransferLayout,
                               VkImage                  srcImage,
                               VkImageSubresourceLayers srcSubresource,
                               const void*              pDstAcquireBarrierNext,
                               VkPipelineStageFlags     dstStageMask,
                               VkAccessFlags            dstAccessMask,
                               VkImageLayout            dstInitialLayout,
                               VkImageLayout            dstTransferLayout,
                               VkImage                  dstImage,
                               VkImageSubresourceLayers dstSubresource,
                               VkFilter                 filter,
                               const void*              pSrcBarrierNext,
                               VkPipelineStageFlags     srcDstStageMask,
                               VkAccessFlags            srcDstAccessMask,
                               VkImageLayout            srcFinalLayout,
                               const void*              pDstBarrierNext,
                               VkPipelineStageFlags     dstDstStageMask,
                               VkAccessFlags            dstDstAccessMask,
                               VkImageLayout            dstFinalLayout,
                               VkOffset2D               srcOffset2D,
                               VkExtent2D               srcExtent2D,
                               VkOffset2D               dstOffset2D,
                               VkExtent2D               dstExtent2D)
{
    VkOffset3D src_offset;
    VkExtent3D src_extent;
    VkOffset3D dst_offset;
    VkExtent3D dst_extent;

    cvkInitOffset3D(&src_offset, srcOffset2D.x, srcOffset2D.y, 0);
    cvkInitExtent3D(&src_extent, srcExtent2D.width, srcExtent2D.height, 1);
    cvkInitOffset3D(&dst_offset, dstOffset2D.x, dstOffset2D.y, 0);
    cvkInitExtent3D(&dst_extent, dstExtent2D.width, dstExtent2D.height, 1);
    cvkCmdTransferBlitImage(commandBuffer,
                            dependencyFlags,
                            pSrcAcquireBarrierNext,
                            srcStageMask,
                            srcAccessMask,
                            srcInitialLayout,
                            srcTransferLayout,
                            srcImage,
                            srcSubresource,
                            src_offset,
                            src_extent,
                            pDstAcquireBarrierNext,
                            dstStageMask,
                            dstAccessMask,
                            dstInitialLayout,
                            dstTransferLayout,
                            dstImage,
                            dstSubresource,
                            dst_offset,
                            dst_extent,
                            filter,
                            pSrcBarrierNext,
                            srcDstStageMask,
                            srcDstAccessMask,
                            srcFinalLayout,
                            pDstBarrierNext,
                            dstDstStageMask,
                            dstDstAccessMask,
                            dstFinalLayout);
}
void cvkSetupVideoSession(VkPhysicalDevice             physicalDevice,
                          VkDevice                     device,
                          const void*                  pVideoSessionNext,
                          uint32_t                     queueFamilyIndex,
                          VkVideoSessionCreateFlagsKHR flags,
                          const VkVideoProfileInfoKHR* pVideoProfile,
                          VkFormat                     pictureFormat,
                          VkExtent2D                   maxCodedExtent,
                          VkFormat                     referencePictureFormat,
                          uint32_t                     maxDpbSlots,
                          uint32_t                     maxActiveReferencePictures,
                          const VkExtensionProperties* pStdHeaderVersion,
                          VkMemoryPropertyFlags        requiredProperties,
                          const void*                  pMemoryNext,
                          const VkAllocationCallbacks* pAllocator,
                          VkVideoSessionKHR*           pVideoSession,
                          VkDeviceMemory*              pMemories,
                          uint32_t*                    pMemoryCount)
{
    cvkCreateVideoSession(device,
                          pVideoSessionNext,
                          queueFamilyIndex,
                          flags,
                          pVideoProfile,
                          pictureFormat,
                          maxCodedExtent,
                          referencePictureFormat,
                          maxDpbSlots,
                          maxActiveReferencePictures,
                          pStdHeaderVersion,
                          pAllocator,
                          pVideoSession);
    (*pMemoryCount) = cvkAllocateVideoSessionMemory(physicalDevice, device, (*pVideoSession), requiredProperties, pMemoryNext, pAllocator, pMemories);
}
